import re
from datetime import date

# Year-first numeric: 2022/11/30, 2022-11-30, 2022.11.30 (separator must be consistent)
_YMD = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")

# Day-first numeric: 30/11/2022, 30-11-2022, 30.11.2022 (ambiguous dates read as DD/MM/YYYY)
_DMY = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")

# Day, month-name, year: 5 March 2024, 5-Mar-2024, 5th of March, 2024
_D_MON_Y = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[\s,.\-]*(?:of\s+)?([A-Za-z]+)\.?[\s,.\-]+(\d{4})",
    re.IGNORECASE,
)

# Month-name, day, year: March 5, 2024; Mar 5th 2024
_MON_D_Y = re.compile(
    r"([A-Za-z]+)\.?[\s,.\-]+(\d{1,2})(?:st|nd|rd|th)?[\s,.\-]+(\d{4})",
    re.IGNORECASE,
)

_MONTH_NAMES = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sep": 9, "sept": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}


def _to_iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = re.sub(r"\s+", " ", s).strip()
    if not text:
        return "INVALID"

    m = _YMD.fullmatch(text)
    if m:
        y, _, mo, d = m.groups()
        return _to_iso(int(y), int(mo), int(d))

    m = _DMY.fullmatch(text)
    if m:
        d, _, mo, y = m.groups()
        return _to_iso(int(y), int(mo), int(d))

    m = _D_MON_Y.fullmatch(text)
    if m:
        d, mon, y = m.groups()
        month = _MONTH_NAMES.get(mon.lower())
        if month is None:
            return "INVALID"
        return _to_iso(int(y), month, int(d))

    m = _MON_D_Y.fullmatch(text)
    if m:
        mon, d, y = m.groups()
        month = _MONTH_NAMES.get(mon.lower())
        if month is None:
            return "INVALID"
        return _to_iso(int(y), month, int(d))

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6,
    "jul": 7, "july": 7, "aug": 8, "august": 8, "sep": 9, "sept": 9,
    "september": 9, "oct": 10, "october": 10, "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAYS = {
    "mon", "monday", "tue", "tues", "tuesday", "wed", "weds", "wednesday",
    "thu", "thur", "thurs", "thursday", "fri", "friday",
    "sat", "saturday", "sun", "sunday",
}

_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")
_ISO_BASIC = re.compile(r"(\d{4})(\d{2})(\d{2})")
_NUMERIC = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")
_NAMED_MDY = re.compile(
    r"([A-Za-z]+)\.?[\s-]+(\d{1,2})(?:st|nd|rd|th)?,?[\s-]+(\d{4})",
    re.IGNORECASE,
)
_NAMED_DMY = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[\s-]+(?:of[\s-]+)?([A-Za-z]+)\.?,?[\s-]+(\d{4})",
    re.IGNORECASE,
)
_NAMED_YMD = re.compile(
    r"(\d{4})[\s-]+([A-Za-z]+)\.?[\s-]+(\d{1,2})(?:st|nd|rd|th)?",
    re.IGNORECASE,
)


def _make(year: int, month: int, day: int) -> str:
    """Return ISO date string if (year, month, day) is a real calendar date, else 'INVALID'."""
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _numeric(a: int, b: int, year: int) -> str:
    # Day-first convention: 'a' is the day and 'b' is the month by default.
    # Fall back to month-first only when the day-first reading is impossible (b > 12).
    if b > 12 and a <= 12:
        return _make(year, a, b)
    return _make(year, b, a)


def _named_month(name: str) -> int | None:
    return _MONTHS.get(name.lower().rstrip("."))


def _strip_weekday(t: str) -> str:
    """Remove a leading weekday name such as 'Tuesday,' or 'Tue.'."""
    m = re.match(r"([A-Za-z]+)\.?,?\s+(.*)$", t)
    if m and m.group(1).lower() in _WEEKDAYS:
        return m.group(2)
    return t


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    t = _strip_weekday(t)

    m = _ISO.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _ISO_BASIC.fullmatch(t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _NUMERIC.fullmatch(t)
    if m:
        return _numeric(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _NAMED_MDY.fullmatch(t)
    if m:
        month = _named_month(m.group(1))
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(2)))

    m = _NAMED_DMY.fullmatch(t)
    if m:
        month = _named_month(m.group(2))
        if month is None:
            return "INVALID"
        return _make(int(m.group(3)), month, int(m.group(1)))

    m = _NAMED_YMD.fullmatch(t)
    if m:
        month = _named_month(m.group(2))
        if month is None:
            return "INVALID"
        return _make(int(m.group(1)), month, int(m.group(3)))

    return "INVALID"

import re
from datetime import date

# Ambiguous numeric dates such as 03/04/2024 (both parts <= 12).
# True -> day-first (DD/MM/YYYY), False -> month-first (MM/DD/YYYY).
AMBIGUOUS_DAY_FIRST = True

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")
_NUM = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")
_DAY_MONTH_YEAR = re.compile(r"(\d{1,2})\s+([a-z]+)\.?\s+(\d{4})")
_MONTH_DAY_YEAR = re.compile(r"([a-z]+)\.?\s+(\d{1,2})\s+(\d{4})")
_ORDINAL = re.compile(r"(\d{1,2})(?:st|nd|rd|th)\b")
_OF = re.compile(r"\bof\b")


def _normalize(s: str) -> str:
    t = s.strip().lower()
    t = t.replace(",", " ")
    t = _OF.sub(" ", t)
    t = _ORDINAL.sub(r"\1", t)
    t = re.sub(r"\s+", " ", t).strip()
    return t


def _make(year: str, month: int, day: str) -> str:
    try:
        d = date(int(year), int(month), int(day))
    except (ValueError, TypeError):
        return "INVALID"
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}"


def _month_number(name: str):
    return _MONTHS.get(name.rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = _normalize(s)
    if not t:
        return "INVALID"

    m = _ISO.fullmatch(t)
    if m:
        y, mo, d = m.groups()
        return _make(y, int(mo), d)

    m = _NUM.fullmatch(t)
    if m:
        a, b, y = m.groups()
        if int(a) > 12:
            d, mo = a, int(b)
        elif int(b) > 12:
            mo, d = int(a), b
        elif AMBIGUOUS_DAY_FIRST:
            d, mo = a, int(b)
        else:
            mo, d = int(a), b
        return _make(y, mo, d)

    m = _DAY_MONTH_YEAR.fullmatch(t)
    if m:
        d, name, y = m.groups()
        mo = _month_number(name)
        if mo is None:
            return "INVALID"
        return _make(y, mo, d)

    m = _MONTH_DAY_YEAR.fullmatch(t)
    if m:
        name, d, y = m.groups()
        mo = _month_number(name)
        if mo is None:
            return "INVALID"
        return _make(y, mo, d)

    return "INVALID"

import re
from datetime import date

# Optional leading weekday, e.g. "Tuesday, ", "Tues. ", "Fri "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)"
    r"\.?,?\s+",
    re.IGNORECASE,
)

_ISO = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")

# Numeric day-first: "31/12/1999", "05/03/2024", "1-2-2000", "3.4.2001"
# Separator must be consistent (backreference \2).
_NUMERIC_DMY = re.compile(r"(\d{1,2})([/.\-])(\d{1,2})\2(\d{4})")

# Day-first with month name: "22nd Feb 1900", "5 March, 2020", "1-Jan-2000", "3.Sept.1999"
_DMY = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[\s\-/.,]+([A-Za-z]{3,9})\.?[\s\-/.,]+(\d{4})"
)

# Month-first with month name: "June 31, 2021", "Feb 22nd 1900", "Sept. 3 1999"
_MDY = re.compile(
    r"([A-Za-z]{3,9})\.?[\s\-/.,]+(\d{1,2})(?:st|nd|rd|th)?[\s\-/.,]+(\d{4})"
)

_MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "jun": 6, "jul": 7,
    "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}


def _to_iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _strip_weekday(text: str) -> str:
    stripped = _WEEKDAY_PREFIX.sub("", text, count=1)
    # Only accept the stripped form if something remains to parse.
    return stripped if stripped else text


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = re.sub(r"\s+", " ", s).strip()
    if not text:
        return "INVALID"

    text = _strip_weekday(text)

    m = _ISO.fullmatch(text)
    if m:
        year, _, month, day = m.groups()
        return _to_iso(int(year), int(month), int(day))

    m = _NUMERIC_DMY.fullmatch(text)
    if m:
        day, _, month, year = m.groups()
        return _to_iso(int(year), int(month), int(day))

    m = _DMY.fullmatch(text)
    if m:
        day, mon, year = m.groups()
        month = _month_number(mon)
        if month is None:
            return "INVALID"
        return _to_iso(int(year), month, int(day))

    m = _MDY.fullmatch(text)
    if m:
        mon, day, year = m.groups()
        month = _month_number(mon)
        if month is None:
            return "INVALID"
        return _to_iso(int(year), month, int(day))

    return "INVALID"
